44	static __always_inline int icmp6_load_type(struct __ctx_buff *ctx, int l4_off, __u8 *type)
45	{
46		return ctx_load_bytes(ctx, l4_off + ICMP6_TYPE_OFFSET, type, sizeof(*type));
47	}
