162	static __always_inline __be32 compute_icmp6_csum(char data[80], __u16 payload_len,
163							 struct ipv6hdr *ipv6hdr)
164	{
165		__be32 sum;
166	
167		/* compute checksum with new payload length */
168		sum = csum_diff(NULL, 0, data, payload_len, 0);
169		sum = ipv6_pseudohdr_checksum(ipv6hdr, IPPROTO_ICMPV6, payload_len,
170					      sum);
171		return sum;
172	}
