345	static __always_inline int __icmp6_handle_ns(struct __ctx_buff *ctx, int nh_off)
346	{
347		union v6addr target, router = CONFIG(router_ipv6);
348		const struct endpoint_info *ep;
349		union macaddr router_mac = CONFIG(interface_mac);
350	
351		if (ctx_load_bytes(ctx, nh_off + ICMP6_ND_TARGET_OFFSET, target.addr,
352				   sizeof(((struct ipv6hdr *)NULL)->saddr)) < 0)
353			return DROP_INVALID;
354	
355		cilium_dbg(ctx, DBG_ICMP6_NS, target.p3, target.p4);
356	
357		if (ipv6_addr_equals(&target, &router)) {
358			return icmp6_send_ndisc_adv(ctx, nh_off, &router_mac, true);
359		}
360	
361	#ifdef USE_LOOPBACK_LB
362		union v6addr service_loopback = CONFIG(service_loopback_ipv6);
363	
364		if (ipv6_addr_equals(&target, &service_loopback)) {
365			union macaddr source_mac;
366	
367			if (ctx_load_bytes(ctx, ETH_ALEN, source_mac.addr, ETH_ALEN) < 0)
368				return DROP_INVALID;
369			return icmp6_send_ndisc_adv(ctx, nh_off, &source_mac, false);
370		}
371	#endif
372	
373		ep = __lookup_ip6_endpoint(&target);
374		if (ep) {
375			if (ep->flags & ENDPOINT_F_HOST) {
376				/* Target must be a node_ip, because of ENDPOINT_F_HOST flag
377				 * and target != router_ip.
378				 *
379				 * We pass these packets to stack to make sure:
380				 *
381				 * 1. The response NA has node IP as source address instead of
382				 * router IP, to address https://github.com/cilium/cilium/issues/14509.
383				 *
384				 * 2. Kernel stack can record a neighbor entry for the
385				 * source IP, to avoid bpf_fib_lookup failure as mentioned at
386				 * https://github.com/cilium/cilium/pull/30837#issuecomment-1960897445.
387				 */
388				return CTX_ACT_OK;
389			}
390			return icmp6_send_ndisc_adv(ctx, nh_off, &router_mac, false);
391		}
392	
